import * as React from "react";
import { useState } from "react";
import Switch, { SwitchProps } from "./Switch";

export interface SwitchOption {
  id: string;
  name: string;
  label: string;
  value: string;
  disabled?: boolean;
}

export interface SwitchGroupProps {
  /**
   * Array of checkbox options to render.
   */
  options: SwitchOption[];

  /**
   * The selected values (value from each option).
   */
  selectedValues: string[];

  /**
   * Callback when any switch in the group changes.
   */
  onChange?: (selected: string[]) => void;

  /**
   * Optional color prop passed to each switch.
   */
  colour?: SwitchProps["colour"];

  /**
   * Layout direction for displaying checkboxes
   */
  layout?: "vertical" | "horizontal";

  /**
   * Shared error message for the group.
   */
  errorText?: string;

  /**
   * Optional className for wrapper div.
   */
  className?: string;
}


export const SwitchGroup: React.FC<SwitchGroupProps> = ({
  options,
  selectedValues,
  onChange,
  colour = "primary",
  layout= "horizontal",
  errorText = "",
  className = "",
}) => {
  

  const [internalValues, setInternalValues] = useState<string[]>([]);
  
  const isControlled = selectedValues !== undefined;
  const currentValues = isControlled ? selectedValues : internalValues;
  
  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
      const { value, checked } = event.target;
  
      const updated = checked
        ? [...currentValues, value]
        : currentValues.filter(val => val !== value);
  
      if (!isControlled) {
        setInternalValues(updated);
      }
  
      if (onChange) {
        onChange(updated);
      }
  };


  return (
    <div className={`switch-group-wrapper ${layout} ${className}`}>
      {options.map((option) => (
        <Switch
          key={option.value}
          id={option.value}
          name={option.name}
          value={option.value}
          label={option.label}
          checked={selectedValues?.includes(option.value)}
          onChange={handleChange}
          colour={colour}
          disabled={option.disabled}
          errorText=""
          className="group-item"
        />
      ))}

      {errorText && (
        <div className="group-error-text">
          <p className="error-text">
            <span>{errorText}</span>
          </p>
        </div>
      )}
    </div>
  );
};

export default SwitchGroup;